'use strict';

// AI: below section was generated by an AI
// Exercise the production preset loader: a temporary UI cache entry must load
// the saved preset from the controller rather than send its placeholder text.
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

const source = fs.readFileSync(path.join(__dirname, '../wled00/data/index.js'), 'utf8');
const start = source.indexOf('function setPreset(i)');
const end = source.indexOf('\nfunction saveP(', start);
assert.ok(start >= 0 && end > start, 'Production preset loader is present');

// Supply only the UI dependencies; keep the actual request-building code intact.
function loadPreset(preset, playlist = false) {
  const sent = [];
  const context = vm.createContext({
    pJson: { 1: preset },
    isPlaylist: () => playlist,
    pName: () => preset.n,
    showToast: () => {},
    requestJson: obj => sent.push(JSON.parse(JSON.stringify(obj)))
  });
  vm.runInContext(source.slice(start, end) + '\nsetPreset(1);', context);
  assert.equal(sent.length, 1);
  return sent[0];
}

test('a pending preset cache entry loads the saved preset by ID', () => {
  assert.deepEqual(loadPreset({ n: 'Solid', win: 'Please refresh the page to see this newly saved command.' }), { ps: 1 });
});

test('cached JSON presets retain their channel mode and omit display metadata', () => {
  const preset = { n: 'White', ql: 'W', seg: [{ id: 0, start: 0, stop: 2, cm: 1, fx: 0 }] };
  assert.deepEqual(loadPreset(preset), { pd: 1, seg: preset.seg });
  assert.equal(preset.n, 'White');
  assert.equal(preset.ql, 'W');
});

test('valid legacy command presets retain the direct-loading path', () => {
  assert.deepEqual(loadPreset({ n: 'Solid', win: 'FX=0' }), { pd: 1, win: 'FX=0' });
});

test('playlists load by ID and turn the controller on', () => {
  assert.deepEqual(loadPreset({ n: 'Playlist', playlist: { ps: [1, 2] } }, true), { ps: 1, on: true });
});
// AI: end
